-- 1. AI Coding Agent
INSERT INTO web_navigation (name, title, content, detail, url, image_url, thumbnail_url, website_data, collection_time, star_rating, tag_name, category_name) VALUES
('claude-code', 'Claude Code', 'Anthropic 推出的终端 AI 编程 Agent，SWE-bench 评分 80.9%，支持大型代码库重构、跨文件批量整改、Git 操作，是当前最强的 AI 编程 Agent。', '## Claude Code\n\nAnthropic 官方 CLI 编程 Agent，多项基准评测领先。\n\n### 核心功能\n- 终端原生 Agent，整库读写、跑测试、Git 操作\n- 长上下文支持超大代码库\n- Agent Teams 多智能体协作\n- 80.9% SWE-bench 评分\n\n### 定价\n- 含于 Claude Pro 订阅 $20/月起\n- Max 档 $100-200/月', 'https://docs.anthropic.com/en/docs/claude-code', 'https://img.tap4.ai/tools/claude.png', 'https://img.tap4.ai/tools/claude-thumb.png', '{"pricing":"Paid","platform":"CLI"}', NOW(), 10, 'coding-agent,anthropic,cli', 'coding-agent'),

('codex-cli', 'OpenAI Codex CLI', 'OpenAI 推出的终端 AI 编程 Agent，支持多智能体并行、云端执行、审计追踪，Terminal-Bench 评分 83.4%。', '## OpenAI Codex CLI\n\nOpenAI 旗舰级 AI 编程 Agent 平台。\n\n### 核心功能\n- 多智能体并行执行\n- 云端沙箱运行\n- 审计追踪\n- 直接操作电脑\n- 长期任务执行\n\n### 定价\n- ChatGPT Plus $20/月\n- Pro $200/月', 'https://github.com/openai/codex', 'https://img.tap4.ai/tools/openai.png', 'https://img.tap4.ai/tools/openai-thumb.png', '{"pricing":"Paid","platform":"CLI"}', NOW(), 10, 'coding-agent,openai,cli', 'coding-agent'),

('cursor', 'Cursor', 'AI 原生 IDE，基于 VS Code，支持多模型切换（Claude、GPT、Gemini），@ 系统精准引用上下文，100万+ 开发者使用。', '## Cursor\n\nAI 原生编程 IDE，500 强企业首选。\n\n### 核心功能\n- @ 系统精准引用文件/文件夹/文档\n- 多模型灵活切换\n- 95ms 自动补全\n- Composer 多文件编辑\n- 1M+ 开发者，估值 $29.3B\n\n### 定价\n- Hobby: 免费\n- Pro: $20/月\n- Pro+: $60/月', 'https://cursor.com', 'https://img.tap4.ai/tools/cursor.png', 'https://img.tap4.ai/tools/cursor-thumb.png', '{"pricing":"Freemium","platform":"Desktop"}', NOW(), 9, 'coding-agent,ide', 'coding-agent'),

('github-copilot', 'GitHub Copilot', 'GitHub 的 AI 编程助手，Agent Mode 自主执行多步编程任务，支持 VS Code/JetBrains/Vim 等多编辑器，性价比最高的付费方案。', '## GitHub Copilot\n\n最广泛的 AI 编码入口，$10/月。\n\n### 核心功能\n- Agent Mode 自主编程\n- PR 审查、Issue 总结\n- 多编辑器支持\n- SOC 2 Type II 认证\n- 多模型（Claude、GPT、Gemini）\n\n### 定价\n- Free: 2000 次/月\n- Pro: $10/月\n- Pro+: $39/月', 'https://github.com/features/copilot', 'https://img.tap4.ai/tools/github.png', 'https://img.tap4.ai/tools/github-thumb.png', '{"pricing":"Freemium","platform":"IDE Extension"}', NOW(), 9, 'coding-agent,github', 'coding-agent'),

('cline', 'Cline', '完全开源的 VS Code 扩展 AI 编程 Agent，支持多模型，5 小时编程约 $6 API 费用，无需订阅。', '## Cline\n\n最强的免费开源 AI 编程 Agent。\n\n### 核心功能\n- 完全开源，免费使用\n- 支持 Anthropic/Gemini/OpenAI 等多模型\n- 终端操作和浏览器访问\n- 多步骤任务编排\n- 完全控制 API 选择\n\n### 定价\n- 免费 + API 费用\n- Teams: $20/用户/月（前 10 席永久免费）', 'https://github.com/cline/cline', 'https://img.tap4.ai/tools/vscode.png', 'https://img.tap4.ai/tools/vscode-thumb.png', '{"pricing":"Free","platform":"IDE Extension"}', NOW(), 9, 'coding-agent,opensource', 'coding-agent'),

('windsurf', 'Windsurf', 'Cognition 推出的 AI 原生 IDE，专注编程体验，$15/月固定费率，Flow State 沉浸式编程体验。', '## Windsurf\n\n注重编程体验的 AI 原生 IDE。\n\n### 核心功能\n- Cascade 智能模式\n- 项目级记忆\n- 5 个并行 Agent\n- 代码库导航流畅\n- 固定费率无限使用\n\n### 定价\n- Free: 有限制\n- Pro: $15/月\n- Business: $30/月', 'https://windsurf.com', 'https://img.tap4.ai/tools/windsurf.png', 'https://img.tap4.ai/tools/windsurf-thumb.png', '{"pricing":"Freemium","platform":"Desktop"}', NOW(), 8, 'coding-agent,ide', 'coding-agent'),

('aider', 'Aider', '开源的终端 AI 结对编程工具，Git 感知，支持任何 LLM，多文件编辑，自动生成 commit。', '## Aider\n\n开源 AI 结对编程利器。\n\n### 核心功能\n- Git 原生感知\n- 支持任何 LLM\n- 多文件编辑\n- 自动生成 commit\n- 代码地图优化\n\n### 定价\n- 免费 + API 费用', 'https://github.com/paul-gauthier/aider', 'https://img.tap4.ai/tools/terminal.png', 'https://img.tap4.ai/tools/terminal-thumb.png', '{"pricing":"Free","platform":"CLI"}', NOW(), 8, 'coding-agent,opensource,cli', 'coding-agent'),

('gemini-cli', 'Gemini CLI', 'Google 官方开源终端 Agent，2026 年 4 月发布，ReAct 循环，100 万 token 上下文，MCP 支持，Apache 2.0 许可。', '## Gemini CLI\n\nGoogle 官方的开源终端 AI Agent。\n\n### 核心功能\n- ReAct 推理循环\n- 100 万 token 上下文\n- MCP 协议支持\n- Apache 2.0 开源\n- 免费使用 Google 账号\n\n### 定价\n- 免费（需 Google 账号）', 'https://github.com/google-gemini/gemini-cli', 'https://img.tap4.ai/tools/gemini.png', 'https://img.tap4.ai/tools/gemini-thumb.png', '{"pricing":"Free","platform":"CLI"}', NOW(), 8, 'coding-agent,google,opensource,cli', 'coding-agent'),

('roocode', 'RooCode', 'Cline 的分支版本，结构化模式，减少幻觉，支持更多定制化的工作流。', '## RooCode\n\nCline 的增强分支。\n\n### 核心功能\n- 结构化模式\n- 减少 AI 幻觉\n- 自定义工作流\n- 多模型支持\n\n### 定价\n- 免费 + API 费用', 'https://github.com/RooVetGit/Roo-Code', 'https://img.tap4.ai/tools/vscode.png', 'https://img.tap4.ai/tools/vscode-thumb.png', '{"pricing":"Free","platform":"IDE Extension"}', NOW(), 7, 'coding-agent,opensource', 'coding-agent'),

-- 2. Autonomous Agent
('devin', 'Devin', 'Cognition 推出的完全自主 AI 软件工程师，云端沙箱运行，Devin 2.0 支持交互式规划，可独立完成复杂开发任务。', '## Devin\n\n全球首个完全自主 AI 软件工程师。\n\n### 核心功能\n- 完全自主编程\n- 云端沙箱环境\n- 交互式规划\n- 独立完成 PR\n- 调试和测试\n\n### 定价\n- $20/月 + ACU 积分', 'https://devin.ai', 'https://img.tap4.ai/tools/devin.png', 'https://img.tap4.ai/tools/devin-thumb.png', '{"pricing":"Paid","platform":"Cloud"}', NOW(), 9, 'autonomous-agent', 'autonomous-agent'),

('openhands', 'OpenHands', '开源自主 AI 软件工程师（原 OpenDevin），可自主解决 GitHub Issue，支持多种 LLM。', '## OpenHands\n\n开源自主 AI 软件工程师。\n\n### 核心功能\n- 自主解决 GitHub Issue\n- 多 LLM 支持\n- 云端 + 本地运行\n- 交互式 Web UI\n\n### 定价\n- 免费开源', 'https://github.com/All-Hands-AI/OpenHands', 'https://img.tap4.ai/tools/openhands.png', 'https://img.tap4.ai/tools/openhands-thumb.png', '{"pricing":"Free","platform":"Cloud/Web"}', NOW(), 8, 'autonomous-agent,opensource', 'autonomous-agent'),

('swe-agent', 'SWE-Agent', '普林斯顿大学开发的自主编程 Agent，可自主解决真实 GitHub Issue，学术前沿。', '## SWE-Agent\n\n普林斯顿 NLP 组开发的自主编程 Agent。\n\n### 核心功能\n- 自主解决 GitHub Issue\n- 基于 LM 的 Agent 架构\n- 学术研究前沿\n- 开源免费\n\n### 定价\n- 免费开源', 'https://github.com/princeton-nlp/SWE-agent', 'https://img.tap4.ai/tools/princeton.png', 'https://img.tap4.ai/tools/princeton-thumb.png', '{"pricing":"Free","platform":"CLI"}', NOW(), 8, 'autonomous-agent,opensource,research', 'autonomous-agent'),

('manus', 'Manus', '被 Meta 收购的自主数字员工 Agent，浏览器扩展，可自动完成各类在线任务。', '## Manus\n\nMeta 收购的自主数字员工平台。\n\n### 核心功能\n- 自主浏览器操作\n- 多步骤任务执行\n- 浏览器扩展\n- 数字员工概念\n\n### 定价\n- 免费/付费', 'https://manus.im', 'https://img.tap4.ai/tools/manus.png', 'https://img.tap4.ai/tools/manus-thumb.png', '{"pricing":"Freemium","platform":"Browser Extension"}', NOW(), 8, 'autonomous-agent,browser', 'autonomous-agent'),

('operator', 'OpenAI Operator', 'ChatGPT 的自主 Web Agent，使用 CUA 技术，可自动完成网页操作，有人类检查点。', '## OpenAI Operator\n\nChatGPT 的自主 Web 操作 Agent。\n\n### 核心功能\n- CUA 技术驱动\n- 自动网页操作\n- 人类检查点\n- 多步骤任务\n\n### 定价\n- ChatGPT Pro 订阅', 'https://operator.chatgpt.com', 'https://img.tap4.ai/tools/openai.png', 'https://img.tap4.ai/tools/openai-thumb.png', '{"pricing":"Paid","platform":"Web"}', NOW(), 8, 'autonomous-agent,browser,openai', 'autonomous-agent'),

